    if (target.id && !force) return
    target.setAttribute('id', 'vp' + [...Array(30)].map(() => Math.random().toString(36)[2]).join(''))
    let tagLine = ''
    for (const attr of analyzation.props) {
        if (target.hasAttribute('vp-' + attr.name)) {
            let value = target.getAttribute('vp-' + attr.name) || ''
            tagLine += ':' + attr.name + '="' + value + '" '
        }
    }
